mapper.select:
SELECT r.record_id AS recordId, r.agent_no AS agentNo, a.agent_name AS agentName, r.mch_no AS mchNo, r.pay_order_id AS payOrderId, r.order_amount AS orderAmount, r.order_currency AS orderCurrency, r.profit_amount AS profitAmount, r.profit_currency AS profitCurrency, r.profit_rate AS profitRate, r.state AS state, r.settle_date AS settleDate, r.created_at AS createdAt FROM t_agent_profit_record r LEFT JOIN t_agent_info a ON a.agent_no = r.agent_no
AND r.agent_no = #{agentNo}
AND r.mch_no = #{mchNo}
AND r.state = #{state}
AND r.created_at >= #{startDate}
AND r.created_at < #{endDate}
ORDER BY r.created_at DESC

SELECT
    settle_date AS settleDate,
    profit_currency AS profitCurrency,
    COUNT(*) AS recordCount,
    SUM(order_amount) AS totalOrderAmount,
    SUM(profit_amount) AS totalProfitAmount
FROM t_agent_profit_record


        AND agent_no = #{agentNo}


        AND state = #{state}


        AND settle_date >= #{startDate}


        AND settle_date < #{endDate}


GROUP BY settle_date, profit_currency
ORDER BY settle_date DESC

